+function Get-RangeStat {
+    param([string]$Root, [string]$Range)
+    $r = [pscustomobject]@{ Range = $Range; Files = 0; Insertions = 0; Deletions = 0; Lines = 0; Error = '' }
+    if (-not $Range -or $Range.StartsWith('-') -or $Range -match '[\s\x00-\x1f]') {
