4666:         $rev = Get-PropertyValue $c 'reviewer' $null
4667:         $fp = if ($null -eq $rev) { $script:BuiltinOpenAiFingerprint } else { [string](Get-PropertyValue $rev 'provider_fingerprint' '') }
4668:         if (-not $fp -or $fp -ne $Fingerprint) { continue }
4669:         $outcome = [string](Get-PropertyValue $c 'bridge_outcome' '')
4670:         if (-not $outcome) { continue }
4671:         $at = ConvertTo-WhenOffset (Get-PropertyValue $c 'when' '')
4672:         if ($null -eq $at) { continue }
4673:         # A failure stamped in the future (clock skew, a mislabelled zone) counts as now:
4674:         # its age is clamped to 0, it is never skipped (F15-4).
4675:         $age = [Math]::Max(0, ($UtcNow - $at.UtcDateTime).TotalMinutes)
4676:         # "Newest" is by COMPLETION (D9, F03-3): a panel's members start together and finish in
4677:         # any order, so a member that started later may have succeeded before an earlier one hit
4678:         # its usage limit. finished_at (0.4.x wave 21), else when + wall_seconds (older entries),
4679:         # else when; ties by n (F02-5).
4680:         $order = ConvertTo-WhenOffset (Get-PropertyValue $c 'finished_at' '')
4681:         if ($null -eq $order) {
4682:             $order = $at
4683:             $ws = 0.0
4684:             if ([double]::TryParse([string](Get-PropertyValue $c 'wall_seconds' ''), [System.Globalization.NumberStyles]::Float, $script:Invariant, [ref]$ws) -and $ws -gt 0) { $order = $at.AddSeconds($ws) }
4685:         }
4686:         $entryN = 0
4687:         [void][int]::TryParse([string](Get-PropertyValue $c 'n' ''), [ref]$entryN)
4688:         $rec = [pscustomobject]@{ At = $at; Order = $order; N = $entryN; Ok = (Test-UsableOutcome $outcome); Class = ''; Code = ''; Message = ''; When = $at.ToString('yyyy-MM-ddTHH:mm:sszzz', $script:Invariant); AgeMinutes = [int][Math]::Max(0, [Math]::Floor($age)); Age = $age; RetryAfter = $null; RetryAfterIso = ''; RetryAfterBasis = ''; Hit = $at; HitIso = ''; Until = $at.AddMinutes(60) }
4689:         if (-not $rec.Ok) {
4690:             $reference = $at
4691:             $pf = Get-PropertyValue $c 'provider_failure' $null
4692:             if ($null -ne $pf) {
4693:                 $rec.Class = [string](Get-PropertyValue $pf 'class' 'unknown')
4694:                 # An entry recorded as auth whose message says usage limit / quota / rate limit
4695:                 # counts as quota (Get-ProviderFailureClass's rule, applied when the ledger is
4696:                 # READ): a 401/403 with a usage-limit text recorded before that rule existed
4697:                 # (Kimi Code's 5-hour limit) stops refusing the endpoint for 24 h as an auth
4698:                 # failure - without anyone editing the ledger.
4699:                 if ($rec.Class -eq 'auth' -and ([string](Get-PropertyValue $pf 'message' '')) -match $script:QuotaTextPattern) { $rec.Class = 'quota' }
4700:                 $rec.Code = [string](Get-PropertyValue $pf 'code' '')
4701:                 $rec.Message = [string](Get-PropertyValue $pf 'message' '')
4702:                 $pfWhen = ConvertTo-WhenOffset (Get-PropertyValue $pf 'when' '')
4703:                 if ($null -ne $pfWhen) { $reference = $pfWhen }
4704:                 $recorded = Get-PropertyValue $pf 'retry_after' $null
4705:                 if ($null -ne $recorded -and "$recorded") { $rec.RetryAfter = ConvertTo-WhenOffset $recorded }
4706:             } else {
4707:                 # older entry: classify its bridge_outcome, lifting an SSE/JSON error payload
4708:                 $parsedOutcome = ConvertFrom-ProviderErrorText -Text $outcome
4709:                 $rec.Class = Get-ProviderFailureClass "$($parsedOutcome.Code) $outcome"
4710:                 $rec.Code = $parsedOutcome.Code
4711:                 $rec.Message = $parsedOutcome.Message
4712:             }
4713:             # an entry recorded without retry_after: read the reset time from its message now
4714:             if ($null -ne $rec.RetryAfter) { $rec.RetryAfterBasis = 'ledger' }
4715:             else {
