4740:             if ($quota.RetryAfter.UtcDateTime -gt $UtcNow) { $h.Quota = $quota }
4741:         } elseif ($quota.Until.UtcDateTime -gt $UtcNow) {
4742:             $h.Quota = $quota
4743:         }
4744:     }
4745:     $h.QuotaKnown = [bool]($h.Quota -and $null -ne $h.Quota.RetryAfter)
4746:     $h.LastLimit = @($sorted | Where-Object { -not $_.Ok -and $_.Class -eq 'quota' -and $_.AgeMinutes -le 24 * 60 }) | Select-Object -First 1
4747:     $h.LastFailure = @($sorted | Where-Object { -not $_.Ok -and $_.AgeMinutes -le 24 * 60 }) | Select-Object -First 1
4748:     if (-not $h.LastLimit -and $h.Quota) { $h.LastLimit = $h.Quota }
4749:     if (-not $h.LastFailure -and $h.Quota) { $h.LastFailure = $h.Quota }
4750:     $h.RecentUsable = @($sorted | Where-Object { $_.Ok -and $_.Age -le 60 }) | Select-Object -First 1
4751:     return $h
4752: }
4753: 
4754: # ----------------------------------------------------------------------------- reviewer roster
4755: #
4756: # The reviewer roster is an ordered list of reviewers the operator is willing to use, first
4757: # choice first. A JSON file (never created by the bridge):
4758: #   CODEX_CONSULT_ROSTER=<path>   that file; it MUST exist (a roster that is asked for and
4759: #                                 missing refuses the run - it is never skipped silently)
4760: #   CODEX_CONSULT_ROSTER=none     no roster at all, the default file is ignored too
4761: #   unset                         <codex home>/codex-consult-roster.json when it exists;
4762: #                                 absent = no roster: everything behaves as without one
4763: #
4764: #   { "roster_version": 1,
4765: #     "reviewers": [ { "provider": "openai", "model": "gpt-5.1" },
4766: #                    { "provider": "ZAI", "model": "glm-5.3" },
4767: #                    { "provider": "local", "model": "m", "auth": "none",
4768: #                      "codex_config": ["model_catalog_json=~/.codex/catalog.json"] } ] }
4769: #
4770: #   provider      required: a [model_providers.<name>] table of the Codex config
4771: #                 (case-sensitive) or openai
4772: #   model         optional: absent = the model resolves as without a roster (the Codex
4773: #                 config's top-level model)
4774: #   codex_config  optional: key=value items with exactly the -CodexConfig rules
4775: #                 (ConvertFrom-CodexConfigItems)
4776: #   auth          optional, only "none": the endpoint needs no credential (a table without
4777: #                 env_key/bearer token then passes the credential check; a table WITH
4778: #                 env_key still needs the variable)
4779: #   panel         optional, "always" (the default) or "weighty": with -Panel a weighty
4780: #                 reviewer joins only on the weighty purposes (framing, decision,
4781: #                 core-contract, acceptance, stuck) or with -PanelAll. The single-reviewer
4782: #                 walk ignores it.
4783: #   engine        optional (0.4.0), "codex" (the default) or "agy": the CLI that carries the
4784: #                 consultation. For agy the provider is a free label (the lineage's
4785: #                 provider, e.g. "gemini"), the model is REQUIRED (the full id with its
4786: #                 tier), codex_config and auth are refused, and one label names one engine
4787: #                 across the roster. Two entries with the same label and different models
4788: #                 are fine (e.g. a "panel": "weighty" entry on the pro model).
4789: #   parallel      optional TOP-LEVEL object (0.4.x wave 21) { "<provider label>": <n> }: a
4790: #                 -Panel runs the members of one endpoint one after another (Get-PanelPlan);
4791: #                 n >= 1 lets that label's members run n at a time. Every key must be a
4792: #                 label the roster uses, every value an integer >= 1.
4793: # Anything else - an unknown key, roster_version other than 1, reviewers not an array or
4794: # empty, the same (provider, model) twice, a file that does not parse - makes the roster
4795: # unusable, and the bridge refuses to run (fail-closed: an existing roster is never
4796: # ignored).
4797: #
4798: # Selection (codex-consult.ps1; codex-providers.ps1 shows the same walk):
4799: #   -Provider given   the roster does not select; the first entry of that provider (by
4800: #                     -Model too when several entries name it) supplies its model when
4801: #                     -Model is empty and its codex_config when -CodexConfig is empty
4802: #   -Thread given     the thread's ledger entry fixes the reviewer; its roster entry
4803: #                     supplies codex_config
4804: #   otherwise         the roster is walked in order and the first entry whose preflight is
4805: #                     available is used (Select-RosterReviewer); every skipped entry is
4806: #                     recorded with its reason. None available: refused.
4807: #   -Panel            every available entry (Select-PanelMembers) runs the same brief, each
4808: #                     as a consultation of its own; members of different endpoints at once,
4809: #                     of one endpoint one after another (Get-PanelPlan, roster "parallel").
4810: 
4811: # Where the roster comes from: { Path ('' when none); FromEnv (CODEX_CONSULT_ROSTER named
4812: # it: it must exist); Disabled (CODEX_CONSULT_ROSTER=none) }.
4813: function Get-RosterPath {
4814:     $p = ([string]$env:CODEX_CONSULT_ROSTER).Trim()
4815:     if ($p -ieq 'none') { return [pscustomobject]@{ Path = ''; FromEnv = $true; Disabled = $true } }
4816:     if ($p) {
4817:         if (-not [IO.Path]::IsPathRooted($p)) { $p = Join-Path (Get-Location).Path $p }
4818:         return [pscustomobject]@{ Path = $p; FromEnv = $true; Disabled = $false }
4819:     }
4820:     $codexHome = Get-CodexHome
4821:     $default = ''
4822:     if ($codexHome) { $default = Join-Path $codexHome 'codex-consult-roster.json' }
4823:     return [pscustomobject]@{ Path = $default; FromEnv = $false; Disabled = $false }
4824: }
4825: 
4826: # { Exists; Path; Disabled (CODEX_CONSULT_ROSTER=none); Entries ({ Position; Provider; Model
4827: # ('' = not given); CodexConfig (string[], already expanded and quoted); Auth ('' | 'none');
4828: # Panel ('always' | 'weighty'); Engine ('codex' | 'agy'); EngineDeclared (the entry names
4829: # its engine) }); Parallel (hashtable, ordinal keys: provider label -> n from the top-level
4830: # "parallel"; empty when absent); Error }. Error is the whole refusal message; the caller
4831: # stops on it.
4832: # $Location: Get-RosterPath (the default).
4833: function Read-ReviewerRoster {
4834:     param($Location = $null)
4835:     if ($null -eq $Location) { $Location = Get-RosterPath }
4836:     $Path = [string]$Location.Path
4837:     $r = [pscustomobject]@{ Exists = $false; Path = $Path; Disabled = [bool]$Location.Disabled; Entries = [object[]]@(); Parallel = (New-Object System.Collections.Hashtable ([StringComparer]::Ordinal)); Error = '' }
4838:     if ($r.Disabled) { return $r }
4839:     if ($Path -and $Location.FromEnv -and -not (Test-Path -LiteralPath $Path)) {
4840:         $r.Error = "the reviewer roster '$Path' named by CODEX_CONSULT_ROSTER does not exist; unset CODEX_CONSULT_ROSTER to use <codex home>/codex-consult-roster.json when it exists, or set it to none for no roster."
4841:         return $r
4842:     }
4843:     if (-not $Path -or -not (Test-Path -LiteralPath $Path)) { return $r }
4844:     $r.Exists = $true
4845:     $why = ''
4846:     $data = $null
4847:     if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
4848:         $why = 'it is not a file'
4849:     } else {
4850:         $text = Read-SharedText -Path $Path
4851:         if (-not $text.Trim()) { $why = 'it is empty or could not be read' }
4852:         else {
4853:             try { $data = ConvertFrom-Json -InputObject $text } catch { $why = "it does not parse: $(ConvertTo-OneLine $_.Exception.Message)" }
4854:             if (-not $why -and -not (Test-IsJsonObject $data)) { $why = 'the top level is not a JSON object' }
4855:         }
4856:     }
4857:     $entries = New-Object System.Collections.Generic.List[object]
4858:     if (-not $why) {
4859:         foreach ($prop in $data.PSObject.Properties) {
4860:             if (@('roster_version', 'reviewers', 'parallel') -cnotcontains $prop.Name) { $why = "unknown key '$($prop.Name)' at the top level (allowed: roster_version, reviewers, parallel)"; break }
4861:         }
4862:     }
4863:     if (-not $why) {
4864:         if (-not $data.PSObject.Properties['roster_version']) { $why = 'roster_version is missing (expected 1)' }
4865:         elseif (-not (Test-IsJsonInteger $data.roster_version) -or [long]$data.roster_version -ne 1) { $why = "roster_version must be 1 (got $(ConvertTo-Json -InputObject $data.roster_version -Compress))" }
4866:     }
4867:     if (-not $why) {
4868:         if (-not $data.PSObject.Properties['reviewers']) { $why = 'reviewers is missing' }
4869:         elseif (-not (Test-IsJsonArray $data.reviewers)) { $why = 'reviewers is not an array' }
4870:         elseif (@($data.reviewers).Count -eq 0) { $why = 'reviewers is empty' }
4871:     }
4872:     if (-not $why) {
4873:         $pos = 0
4874:         foreach ($item in @($data.reviewers)) {
4875:             $pos++
4876:             $at = "entry $pos"
4877:             if (-not (Test-IsJsonObject $item)) { $why = "$at is not an object"; break }
4878:             foreach ($prop in $item.PSObject.Properties) {
4879:                 if (@('provider', 'model', 'codex_config', 'auth', 'panel', 'engine') -cnotcontains $prop.Name) { $why = "$at has an unknown key '$($prop.Name)' (allowed: provider, model, codex_config, auth, panel, engine)"; break }
4880:             }
4881:             if ($why) { break }
4882:             $provider = $null
4883:             if ($item.PSObject.Properties['provider']) { $provider = $item.provider }
4884:             if (-not ($provider -is [string]) -or -not $provider.Trim() -or $provider -cne $provider.Trim()) { $why = "$at needs a provider: a non-empty string without surrounding blanks"; break }
4885:             $model = ''
4886:             if ($item.PSObject.Properties['model']) {
4887:                 $mv = $item.model
4888:                 if (-not ($mv -is [string]) -or -not $mv.Trim() -or $mv -cne $mv.Trim()) { $why = "${at}: model must be a non-empty string without surrounding blanks (omit it to use the Codex config's model)"; break }
4889:                 $model = $mv
4890:             }
4891:             $cfgItems = [string[]]@()
4892:             if ($item.PSObject.Properties['codex_config']) {
4893:                 $cv = $item.codex_config
4894:                 $allStrings = (Test-IsJsonArray $cv)
4895:                 if ($allStrings) { foreach ($x in @($cv)) { if (-not ($x -is [string])) { $allStrings = $false } } }
4896:                 if (-not $allStrings) { $why = "${at}: codex_config must be an array of key=value strings"; break }
4897:                 $parsed = ConvertFrom-CodexConfigItems -Values ([string[]]@($cv)) -Label 'codex_config'
4898:                 if ($parsed.Error) { $why = "${at}: $($parsed.Error.TrimEnd([char]'.'))"; break }
4899:                 $cfgItems = $parsed.Items
4900:             }
4901:             $auth = ''
4902:             if ($item.PSObject.Properties['auth']) {
4903:                 if (-not ($item.auth -is [string]) -or $item.auth -cne 'none') { $why = "${at}: auth may only be ""none"" (an endpoint that needs no credential; omit it otherwise)"; break }
4904:                 $auth = 'none'
4905:             }
4906:             $panelWeight = 'always'
4907:             if ($item.PSObject.Properties['panel']) {
4908:                 if (-not ($item.panel -is [string]) -or @('always', 'weighty') -cnotcontains $item.panel) { $why = "${at}: panel must be ""always"" or ""weighty"" (got $(ConvertTo-Json -InputObject $item.panel -Compress))"; break }
4909:                 $panelWeight = $item.panel
4910:             }
4911:             $engine = 'codex'
4912:             $engineDeclared = $false
4913:             if ($item.PSObject.Properties['engine']) {
4914:                 if (-not ($item.engine -is [string]) -or $script:EngineNames -cnotcontains $item.engine) { $why = "${at}: engine must be one of: $($script:EngineNames -join ', ') (got $(ConvertTo-Json -InputObject $item.engine -Compress))"; break }
4915:                 $engine = $item.engine
4916:                 $engineDeclared = $true
4917:             }
4918:             if ($engine -ne 'codex') {
4919:                 if (-not $model) { $why = "${at}: engine $engine needs a model (the full model id, e.g. $((Get-EngineSpec $engine).ModelExample))"; break }
4920:                 if ($item.PSObject.Properties['codex_config']) { $why = "${at}: codex_config does not apply to engine $engine (it configures codex exec)"; break }
4921:                 if ($item.PSObject.Properties['auth']) { $why = "${at}: auth does not apply to engine $engine (the $engine CLI keeps its own sign-in)"; break }
4922:             }
4923:             $other = @($entries | Where-Object { $_.Provider -ceq $provider -and $_.Engine -ne $engine }) | Select-Object -First 1
4924:             if ($other) { $why = "entries $($other.Position) and $pos use the provider label '$provider' with two engines ($($other.Engine), $engine); a label names one engine"; break }
4925:             $dup = @($entries | Where-Object { $_.Provider -ceq $provider -and $_.Model -ceq $model }) | Select-Object -First 1
4926:             if ($dup) {
4927:                 $label = if ($model) { Format-Lineage -Provider $provider -Model $model } else { "$provider (no model)" }
4928:                 $why = "entries $($dup.Position) and $pos are the same reviewer $label"; break
4929:             }
4930:             $entries.Add([pscustomobject]@{ Position = $pos; Provider = $provider; Model = $model; CodexConfig = $cfgItems; Auth = $auth; Panel = $panelWeight; Engine = $engine; EngineDeclared = $engineDeclared })
4931:         }
4932:     }
4933:     if (-not $why -and $data.PSObject.Properties['parallel']) {
4934:         $pv = $data.parallel
4935:         if (-not (Test-IsJsonObject $pv)) {
4936:             $why = "parallel must be an object {""<provider label>"": <n>} (got $(ConvertTo-Json -InputObject $pv -Compress))"
4937:         } else {
4938:             foreach ($prop in $pv.PSObject.Properties) {
4939:                 if (@($entries | Where-Object { $_.Provider -ceq $prop.Name }).Count -eq 0) { $why = "parallel names the provider label '$($prop.Name)', which no entry of the roster uses"; break }
4940:                 if (-not (Test-IsJsonInteger $prop.Value) -or [double]$prop.Value -lt 1) { $why = "parallel.$($prop.Name) must be an integer >= 1 (got $(ConvertTo-Json -InputObject $prop.Value -Compress))"; break }
4941:                 $r.Parallel[$prop.Name] = [int]$prop.Value
4942:             }
4943:         }
4944:     }
4945:     if ($why) {
4946:         $r.Error = "the reviewer roster '$Path' is not usable: $why. Fix it or move it aside - an existing roster is never ignored (CODEX_CONSULT_ROSTER names another file)."
4947:         return $r
4948:     }
4949:     $r.Entries = [object[]]$entries.ToArray()
4950:     return $r
4951: }
4952: 
4953: # The roster entry of a provider (-Provider, or a thread's reviewer): the first entry that
4954: # names it; when several do and $Model is given, the first whose model equals $Model. $null
4955: # when none names it.
4956: function Find-RosterEntry {
4957:     param($Roster, [string]$Provider, [string]$Model = '')
4958:     if (-not $Roster -or -not $Roster.Exists) { return $null }
4959:     $byProvider = @($Roster.Entries | Where-Object { $_.Provider -ceq $Provider })
4960:     if ($byProvider.Count -eq 0) { return $null }
4961:     if ($Model -and $byProvider.Count -gt 1) {
4962:         $exact = @($byProvider | Where-Object { $_.Model -ceq $Model }) | Select-Object -First 1
4963:         if ($exact) { return $exact }
4964:     }
4965:     return $byProvider[0]
4966: }
4967: 
4968: # The preflight decision for one identity, local checks only (credentials, then the
4969: # endpoint's recorded health): { State available|unavailable|unknown; Preflight (the
4970: # ledger's preflight text); Reason (one phrase: why a roster walk skips it); Refusal (the
4971: # refusal message of a real run); Label (the dry-run line); (wave 24, D14 - what every
4972: # availability surface shows) Kind ('' | identity | unresolved | credentials | auth | quota |
4973: # quota-unknown-reset | unknown); Hit and Until (DateTimeOffset or $null: when the recorded
4974: # failure happened and when the endpoint is expected back - a known reset, or Hit + 60 min);
4975: # Credential (the credential result, $null before the check) }. In this order:
4976: #   identity error / unresolved  unavailable / unknown
4977: #   credentials missing          unavailable (Get-ProviderCredential, Get-EngineCredential)
4978: #   auth failure <= 24 h         unavailable: auth failed <when>: <message>
4979: #   usage limit with a known     unavailable: usage limit until <iso>
4980: #   reset in the future
4981: #   usage limit without a reset  -RosterWalk: unavailable: usage limit hit <iso>, reset
4982: #   time, hit < 60 min ago       unknown; retry after <iso + 60 min> (a later roster entry
4983: #                                exists to fall back to); otherwise available -
4984: #                                Format-QuotaWarning warns about it
4985: #   credentials unknown          unknown (wave 24: a recorded auth failure or usage limit
4986: #                                outranks a sign-in that was not checked - the hook's
4987: #                                -NoNetwork line names what is out)
4988: # $Health: Get-EndpointHealth of the identity's endpoint ($null: none known).
4989: function Get-PreflightVerdict {
4990:     param($Identity, $Config, [string]$Launcher, $Health, [hashtable]$LoginCache = $null, [switch]$Anonymous, [switch]$RosterWalk, [switch]$NoNetwork)
4991:     $v = [pscustomobject]@{ State = 'available'; Preflight = ''; Reason = ''; Refusal = ''; Label = ''; Kind = ''; Hit = $null; Until = $null; Credential = $null }

4989: function Get-PreflightVerdict {
4990:     param($Identity, $Config, [string]$Launcher, $Health, [hashtable]$LoginCache = $null, [switch]$Anonymous, [switch]$RosterWalk, [switch]$NoNetwork)
4991:     $v = [pscustomobject]@{ State = 'available'; Preflight = ''; Reason = ''; Refusal = ''; Label = ''; Kind = ''; Hit = $null; Until = $null; Credential = $null }
4992:     $p = [string]$Identity.Provider
4993:     $engine = [string]$Identity.Engine
4994:     if (-not $engine) { $engine = 'codex' }
4995:     if ($Identity.Error) {
4996:         $v.State = 'unavailable'
4997:         $v.Kind = 'identity'
4998:         $v.Reason = $Identity.Error
4999:         $v.Preflight = "unavailable: $($Identity.Error)"
5000:         $v.Refusal = $Identity.Error
5001:         $v.Label = "unavailable ($($Identity.Error)) - a real run is refused"
5002:         return $v
5003:     }
5004:     if (-not $Identity.Resolved) {
5005:         $reason = "reviewer identity unresolved: $($Identity.Note)"
5006:         $v.State = 'unknown'
5007:         $v.Kind = 'unresolved'
5008:         $v.Preflight = "unknown: $reason"
5009:         $v.Reason = $v.Preflight
5010:         $v.Refusal = "provider $($p): availability could not be established ($reason); pass -SkipPreflight to launch anyway, or fix the check"
5011:         $v.Label = "unknown ($reason) - a real run is refused: $($v.Refusal)"
5012:         return $v
5013:     }
5014:     if ($engine -ne 'codex') {
5015:         # An engine keeps its own sign-in: its credential check (agy: `agy models`, or a usable
5016:         # reply on this endpoint within the last 60 minutes - the auth / quota rules below
5017:         # still apply).
5018:         $cred = Get-EngineCredential -Engine $engine -Launcher $Launcher -LoginCache $LoginCache -NoNetwork:$NoNetwork -Health $Health
5019:     } else {
5020:         $table = $null
5021:         if ($Config -and $Config.Exists -and $Config.Ok) {
5022:             $pt = Get-ProviderTable -Config $Config -Name $p
5023:             if ($pt.Found) { $table = $pt.Table }
5024:         }
5025:         $cred = Get-ProviderCredential -Name $p -Table $table -Launcher $Launcher -LoginCache $LoginCache -Anonymous:$Anonymous
5026:     }
5027:     $v.Credential = $cred
5028:     $v.Preflight = $cred.Detail
5029:     $v.Reason = $cred.Detail
5030:     if ($cred.State -eq 'missing') {
5031:         $v.State = 'unavailable'
5032:         $v.Kind = 'credentials'
5033:         $v.Refusal = "provider $p is not usable: $($cred.Reason); nothing was started (run codex-providers.ps1 for the full picture)"
5034:         $v.Label = "unavailable ($($cred.Reason)) - a real run is refused: $($v.Refusal)"
5035:     } elseif ($Health -and $Health.Auth) {
5036:         $v.State = 'unavailable'
5037:         $v.Kind = 'auth'
5038:         $v.Hit = $Health.Auth.Hit
5039:         $v.Reason = "auth failed $($Health.Auth.When): $($Health.Auth.Message)"
5040:         $v.Preflight = "unavailable: $($v.Reason)"
5041:         $v.Refusal = "provider $p is not usable: the last run on this endpoint was rejected as unauthenticated at $($Health.Auth.When) ($($Health.Auth.Message)); if you rotated the credential, pass -SkipPreflight once"
5042:         $v.Label = "unavailable ($($v.Reason)) - a real run is refused: $($v.Refusal)"
5043:     } elseif ($Health -and $Health.Quota -and $Health.QuotaKnown) {
5044:         $v.State = 'unavailable'
5045:         $v.Kind = 'quota'
5046:         $v.Hit = $Health.Quota.Hit
5047:         $v.Until = $Health.Quota.RetryAfter
5048:         $v.Reason = "usage limit until $($Health.Quota.RetryAfterIso)"
5049:         $v.Preflight = "unavailable: $($v.Reason)"
5050:         $v.Refusal = "provider $p is not usable: its usage limit (hit at $($Health.Quota.When): $($Health.Quota.Message)) lasts until $($Health.Quota.RetryAfterIso); nothing was started (pass -SkipPreflight to launch anyway)"
5051:         $v.Label = "unavailable ($($v.Reason)) - a real run is refused: $($v.Refusal)"
5052:     } elseif ($RosterWalk -and $Health -and $Health.Quota) {
5053:         $untilIso = Format-OffsetIso $Health.Quota.Until
5054:         $v.State = 'unavailable'
5055:         $v.Kind = 'quota-unknown-reset'
5056:         $v.Hit = $Health.Quota.Hit
5057:         $v.Until = $Health.Quota.Until
5058:         $v.Reason = "usage limit hit $($Health.Quota.HitIso), reset unknown; retry after $untilIso"
5059:         $v.Preflight = "unavailable: $($v.Reason)"
5060:         $v.Refusal = "provider $p is not usable: it hit a usage limit at $($Health.Quota.HitIso) ($($Health.Quota.Message)) and named no reset time - out for 60 minutes, until $untilIso; nothing was started"
5061:         $v.Label = "unavailable ($($v.Reason)) - a real run is refused: $($v.Refusal)"
5062:     } elseif ($cred.State -eq 'unknown') {
5063:         $v.State = 'unknown'
5064:         $v.Kind = 'unknown'
5065:         $v.Refusal = "provider $($p): availability could not be established ($($cred.Reason)); pass -SkipPreflight to launch anyway, or fix the check"
5066:         $v.Label = "unknown ($($cred.Reason)) - a real run is refused: $($v.Refusal)"
5067:     } else {
5068:         $v.Label = "available ($($cred.Detail))"
5069:     }
5070:     return $v
5071: }
5072: 
5073: # The warning of a usage limit that does not refuse the run: one without a known reset time
5074: # (<= 60 min old), or - with -SkipPreflight - one whose reset time lies ahead. '' otherwise.
5075: function Format-QuotaWarning {
5076:     param($Identity, $Health, [switch]$SkipPreflight)
5077:     if (-not $Health -or -not $Health.Quota) { return '' }
5078:     $q = $Health.Quota
5079:     if ($Health.QuotaKnown) {
5080:         if (-not $SkipPreflight) { return '' }
5081:         return "provider $($Identity.Provider) hit a usage limit $($q.AgeMinutes) min ago that lasts until $($q.RetryAfterIso): $($q.Message)"
5082:     }
5083:     return "provider $($Identity.Provider) hit a usage limit $($q.AgeMinutes) min ago: $($q.Message)"
5084: }
5085: 
5086: # The roster walk: the first entry whose preflight verdict (Get-PreflightVerdict
5087: # -RosterWalk) is available. $Model (an explicit -Model without -Provider) restricts the walk
5088: # to the entries that resolve to that model. -SkipPreflight takes the first entry unchecked -
5089: # except for an engine's launch invariant (wave 23, D4: muse's billing guard), which skips an
5090: # entry ("refused: ...") with and without -SkipPreflight.
5091: # { Entry; Identity; Verdict; Skipped (object[] of { provider; model; reason }, in roster
5092: # order - never a List: @() over a List property fails on Windows PowerShell 5.1);
5093: # Considered (entries walked); Error ('' or the refusal: none available / no entry for
