5465: # The one-line availability view (D17; the SessionStart hook, codex-providers.ps1 -Short): what is
5466: # OUT and what was NOT CHECKED, per roster entry, then the count -
5467: #   codex-consult: out - openai :: gpt-6-astra (until Sun 20:35, in 2d 10h), gemini :: * (until
5468: #   Sun 21:30, in 2d 11h); 9 of 11 reviewers available
5469: #   codex-consult: all 11 reviewers available
5470: # The entries of one endpoint group collapse to '<label> :: *' (labels of a merged group joined by
5471: # '+') when there are at least two and all share the state and the phrase; otherwise one clause
5472: # per entry. Nothing is cut. The count names the not-checked entries ("7 of 11 reviewers
5473: # available, 2 out, 2 not checked") whenever there are any (then the three counts do not add up
5474: # from the clauses alone). $Noun: 'reviewers' (a roster) or 'providers' (none).
5475: function Format-AvailabilityLine {
5476:     param($Availability, [string]$Noun = 'reviewers', [string]$Prefix = 'codex-consult: ', [string]$Suffix = '')
5477:     $recs = @($Availability.Records | Where-Object { $_ })
5478:     $n = $recs.Count
5479:     $noun = $(if ($n -eq 1) { $Noun -replace 's$', '' } else { $Noun })
5480:     if ($n -eq 0) { return "${Prefix}no $Noun to check$Suffix" }
5481:     $a = @($recs | Where-Object { $_.State -eq 'available' }).Count
5482:     $o = @($recs | Where-Object { $_.State -eq 'out' }).Count
5483:     $c = @($recs | Where-Object { $_.State -eq 'not checked' }).Count
5484:     if ($o -eq 0 -and $c -eq 0) { return "${Prefix}all $n $noun available$Suffix" }
5485:     $parts = New-Object System.Collections.Generic.List[string]
5486:     foreach ($state in @('out', 'not checked')) {
5487:         $these = @($recs | Where-Object { $_.State -eq $state })
5488:         if ($these.Count -eq 0) { continue }
5489:         $clauses = New-Object System.Collections.Generic.List[string]
5490:         $done = @{}
5491:         foreach ($r in $these) {
5492:             if ($done.ContainsKey($r.Group)) { continue }
5493:             $group = @($recs | Where-Object { $_.Group -eq $r.Group })
5494:             $same = @($group | Where-Object { $_.State -eq $state -and $_.Short -ceq $r.Short })
5495:             if ($group.Count -ge 2 -and $same.Count -eq $group.Count) {
5496:                 $done[$r.Group] = $true
5497:                 $labels = @($group | ForEach-Object { $_.Provider } | Select-Object -Unique)
5498:                 $clauses.Add("$($labels -join '+') :: * ($($r.Short))")
5499:             } else {
5500:                 $clauses.Add("$($r.Lineage) ($($r.Short))")
5501:             }
5502:         }
5503:         $parts.Add("$state - $($clauses.ToArray() -join ', ')")
5504:     }
5505:     $tail = "$a of $n $noun available"
5506:     if ($c -gt 0) { $tail += ", $o out, $c not checked" }
5507:     $parts.Add($tail)
5508:     return "$Prefix$($parts.ToArray() -join '; ')$Suffix"
5509: }
