648: # One more turn (an engine's denial retry and format repair; wave 24: the timeout continuation
649: # of every engine, codex included) under the SAME task lock and recovery record as the run: the
650: # record goes launching -> running (child pid, start time, `events` = this turn's event stream)
651: # before the process is waited on; a timeout kills the process tree, and survivors are recorded
652: # (state survivors) and keep the record.
653: # -PromptPath / -PromptText (wave 23, D1): the turn's own prompt file, written first (muse
654: # names it in its argv; its stdin is then empty). Right before the start the engine's launch
655: # invariant (D4; read afresh - wave 24, F15-1) and, for an engine other than codex, the .cmd
656: # %-hazard (F02-14) are checked again: a refusal starts nothing.
657: # Reads the run's $pendingRecord, $pendingPath, $engineLauncher, $engineName and $repoRoot.
658: # { Exit (-1 unless it exited); Problem ('' or why the turn did not complete); Wall;
659: # KeepPending; Stderr (UTF-8 text); Started (a process was started: one more engine turn -
660: # for muse one more subscription prompt) }.
661: function Invoke-EngineTurn {
662:     param([string[]]$Argv, [string]$StdinText, [string]$EventsPath, [string]$StdinPath, [string]$StderrPath, [int]$Timeout, [string]$Note, [string]$PromptPath = '', [string]$PromptText = '')
663:     $t = [pscustomobject]@{ Exit = -1; Problem = ''; Wall = 0; KeepPending = $false; Stderr = ''; Started = $false }
664:     if ($PromptPath) { Write-Utf8NoBom -Path $PromptPath -Text $PromptText }
665:     Write-Utf8NoBom -Path $StdinPath -Text $StdinText
666:     $refusal = Get-EngineLaunchBlock -Engine $engineName -Fresh
667:     if (-not $refusal -and $engineName -ne 'codex') { $refusal = Get-CmdArgvHazard -Launcher $engineLauncher -Argv $Argv }
668:     if ($refusal) {
669:         $t.Problem = "refused before launch: $refusal"
670:         return $t
671:     }
672:     $watch = [System.Diagnostics.Stopwatch]::StartNew()
673:     $pendingRecord.state = 'launching'
674:     $pendingRecord.note = "$Note being started; its pid is not recorded yet"
675:     try { Write-PendingFile -Path $pendingPath -Record $pendingRecord } catch {
676:         $t.Problem = "could not write the recovery record ($(ConvertTo-OneLine $_.Exception.Message)); the turn was not started"
677:         return $t
678:     }
679:     $proc = $null
680:     try {
681:         $proc = Start-Process -FilePath $engineLauncher -ArgumentList ((($Argv | ForEach-Object { ConvertTo-ProcArg $_ }) -join ' ')) `
682:             -WorkingDirectory $repoRoot -NoNewWindow -PassThru `
683:             -RedirectStandardOutput $EventsPath `
684:             -RedirectStandardError $StderrPath `
685:             -RedirectStandardInput $StdinPath
686:     } catch {
687:         $t.Problem = "could not start $engineName - $(ConvertTo-OneLine $_.Exception.Message)"
688:     }
689:     if ($proc) {
690:         if ($script:LegacyPS) { try { $null = $proc.Handle } catch { } }
691:         $t.Started = $true
692:         $registered = $true
693:         try {
694:             $pendingRecord.state = 'running'
695:             $pendingRecord.child_pid = $proc.Id
696:             $pendingRecord.child_start_time = [string](Get-ProcessStartIso -ProcessId $proc.Id)
697:             $pendingRecord.note = $Note
698:             $evRel = Get-RepoRelativePath -Root $repoRoot -Path $EventsPath
699:             $pendingRecord.events = $(if ($evRel) { $evRel } else { $EventsPath })
700:             Write-PendingFile -Path $pendingPath -Record $pendingRecord
701:         } catch {
702:             $registered = $false
703:             $t.Problem = "could not register the $Note process ($(ConvertTo-OneLine $_.Exception.Message)); it was stopped"
704:             # the record on disk still says launching: so does the one in memory
705:             $pendingRecord.state = 'launching'; $pendingRecord.child_pid = $null; $pendingRecord.child_start_time = ''
706:             $null = Stop-ProcessTree -Process $proc
707:         }
708:         if ($registered) {
709:             if (-not $proc.WaitForExit($Timeout * 1000)) {
710:                 $surv = Stop-ProcessTree -Process $proc   # [int[]]; never wrap in @()
711:                 $t.Problem = "timeout after $Timeout s (process tree killed)"
712:                 if ($surv.Count -gt 0) {
713:                     $t.Problem = "timeout after $Timeout s (process tree killed; $($surv.Count) processes survived: pid $($surv -join ', '))"
714:                     $t.KeepPending = $true
715:                     try {
716:                         $pendingRecord.state = 'survivors'
717:                         $pendingRecord.survivors = [object[]]@(New-SurvivorEntries -Pids $surv)
718:                         Write-PendingFile -Path $pendingPath -Record $pendingRecord
719:                     } catch { }
720:                 }
721:             } else {
722:                 $t.Exit = $proc.ExitCode
723:             }
724:         }
725:     }
726:     $watch.Stop()
727:     $t.Wall = [math]::Round($watch.Elapsed.TotalSeconds, 1)
728:     $t.Stderr = Read-SharedText -Path $StderrPath
729:     return $t
730: }
