732: # The read-only check of an engine other than codex (agy A17, widened in wave 18 - F09-1/F10-1;
733: # muse wave 23, D12): '' when nothing the
734: # review must not touch changed during the run, else the reason - the working tree (tracked
735: # or untracked files; the paths that changed), the collab directory (EVERY file under it,
736: # recursively: every task's stores and handoffs - outside the tree fingerprint; the run's own
737: # <task>/handoffs/NN-<prefix>-<slug>.* files and the .consult.* lock and recovery files
738: # excepted), the brief, an artifact. The check cannot tell who changed a file, so the text
739: # does not blame the reviewer (F09-3). Gitignored paths, submodules and files outside the
740: # repository stay unmonitored (README "Engines", F12) - and so do reads. $CollabShown: the
741: # collab directory as shown in front of its paths ('.collab/' inside the repository, ''
742: # otherwise). The closing words are the engine row's TreeNote (D11).
743: function Get-EngineTreeProblem {
744:     param($RevBefore, $RevAfter, [bool]$BriefChanged, [string[]]$ChangedArtifacts, [hashtable]$CollabBefore, [hashtable]$CollabAfter, [string[]]$OwnPrefixes, [string]$Engine, [string]$CollabShown = '')
745:     $cut = { param([string[]]$Names) $n = @($Names); $list = (@($n | Select-Object -First 5) -join ', '); if ($n.Count -gt 5) { $list += ', ...' }; "$($n.Count) file$(if ($n.Count -ne 1) { 's' }): $list" }
746:     $why = New-Object System.Collections.Generic.List[string]
747:     if ($RevBefore.tree_sha256 -ne $RevAfter.tree_sha256) {
748:         $paths = Get-ManifestChanges -Before $RevBefore.manifest -After $RevAfter.manifest
749:         $why.Add("the working tree changed during the run (by the reviewer or anyone else): $(& $cut $paths)")
750:     }
751:     $collab = Compare-DirectorySnapshot -Before $CollabBefore -After $CollabAfter -IgnorePrefixes $OwnPrefixes
752:     if ($collab.Count -gt 0) { $why.Add("the collab directory changed during the run (by the reviewer or anyone else): $(& $cut ([string[]]@($collab | ForEach-Object { $CollabShown + $_ })))") }
753:     if ($BriefChanged) { $why.Add('the brief changed during the run (by the reviewer or anyone else)') }
754:     if (@($ChangedArtifacts).Count -gt 0) { $why.Add("artifact(s) changed during the run (by the reviewer or anyone else): $(@($ChangedArtifacts) -join ', ')") }
755:     if ($why.Count -eq 0) { return '' }
756:     $note = [string](Get-EngineSpec -Name $Engine).TreeNote
757:     if (-not $note) { $note = "$Engine's sandbox does not block writes" }
758:     return (($why.ToArray() -join '; ') + " - $note")
759: }
